-- Phone push notifications for subscription alerts -------------------------------
-- Already applied to the live project, together with the Edge Function in
-- supabase/functions/push. Kept here so the database can be rebuilt.

create extension if not exists pg_cron;
create extension if not exists pg_net;

-- Server-side settings. The VAPID private key is generated by the Edge Function on first use
-- and is never readable by the browser: RLS is on, there are no policies, and the table is
-- revoked from the anon and authenticated roles. Only the service role can touch it.
create table public.push_config (
  id            int primary key default 1 check (id = 1),
  vapid_public  text,
  vapid_private text,
  contact       text,
  cron_secret   text not null
                default (replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '')),
  created_at    timestamptz not null default now()
);
insert into public.push_config (id) values (1);
alter table public.push_config enable row level security;
revoke all on public.push_config from anon, authenticated;

-- One row per phone/browser that turned notifications on.
create table public.push_subscriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  endpoint   text not null unique,
  p256dh     text not null,
  auth       text not null,
  user_agent text,
  created_at timestamptz not null default now()
);
alter table public.push_subscriptions enable row level security;
create policy "owner access" on public.push_subscriptions
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke all on public.push_subscriptions from anon;

-- Remembers which due dates were already notified, so each charge alerts only once.
create table public.push_log (
  item_id  uuid not null references public.recurring_items (id) on delete cascade,
  due_date date not null,
  sent_at  timestamptz not null default now(),
  primary key (item_id, due_date)
);
alter table public.push_log enable row level security;
revoke all on public.push_log from anon, authenticated;

-- Items whose alert window has opened and that have not been notified yet.
create or replace function public.push_due_alerts()
returns table (user_id uuid, item_id uuid, name text, kind text, amount numeric,
               next_due date, days_until int, is_trial boolean)
language sql
stable
security definer
set search_path = public
as $$
  select i.user_id, i.id, i.name, i.kind, i.amount::numeric, n.d,
         (n.d - public.kl_today())::int,
         coalesce(i.trial_ends_on >= public.kl_today(), false)
  from public.recurring_items i
  cross join lateral (
    select public.recurring_next_due(i.anchor_date, i.cycle, public.kl_today()) as d
  ) n
  where i.status = 'active'
    and i.alert_days is not null
    and (i.ends_on is null or n.d <= i.ends_on)
    and (n.d - public.kl_today()) <= i.alert_days
    and not exists (select 1 from public.push_log l where l.item_id = i.id and l.due_date = n.d)
    and exists (select 1 from public.push_subscriptions s where s.user_id = i.user_id)
  order by n.d;
$$;

revoke execute on function public.push_due_alerts() from public, anon, authenticated;
grant  execute on function public.push_due_alerts() to service_role;

-- Every day at 09:00 Malaysia time (01:00 UTC) ask the Edge Function to send due alerts.
-- The bearer token is the project's public anon key (it only gets the request past the
-- function gateway); the x-cron-secret header is what actually authorises the job.
select cron.schedule(
  'subscription-push-alerts',
  '0 1 * * *',
  $cmd$
  select net.http_post(
    url     := 'https://sqtfdpxhtnspdnthabwj.supabase.co/functions/v1/push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNxdGZkcHhodG5zcGRudGhhYndqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTE0NDQyMDksImV4cCI6MjEwNzAyMDIwOX0._Zv9tc36cUmLc_RInmJjke_Q3s0MW6E-xq49L3qd7JI',
      'x-cron-secret', (select cron_secret from public.push_config where id = 1)),
    body    := jsonb_build_object('action', 'run'));
  $cmd$
);
